# -*- coding: utf-8 -*-  
import re

with open('index.html', 'r', encoding='utf-8') as f:
    html = f.read()

html = html.replace('<i class="fa-solid fa-users-gear"></i> ประมาณการ ปวช.1', '<i class="fa-solid fa-users-gear"></i> ข้อมูลผู้เรียน')

html = re.sub(r'<div class="header-titles">[\s\S]*?</div>', '''<div class="header-titles">
                    <h2><i class="fa-solid fa-users-gear" style="color: #2563eb;"></i> ข้อมูลผู้เรียน และ ประมาณการ</h2>
                    <p>ระบบจัดเก็บสถิติจำนวนนักเรียนและประมาณการผู้เรียน ปวช.1</p>
                </div>''', html, count=1)

toggleRegex = r'<div class="admin-only hidden no-print" style="display:flex; align-items:center; gap:0\.5rem; background:var\(--bg-muted\); padding:0\.4rem 0\.8rem; border-radius:var\(--radius-full\); border:1px solid var\(--border-color\);">\s*<input type="checkbox" id="estimateToggleSwitch".*?>\s*<label for="estimateToggleSwitch".*?>เปิดใช้งานแท็บนี้</label>\s*</div>'
html = re.sub(toggleRegex, '', html)

import base64
popHtml = base64.b64decode('').decode('utf-8')

html = html.replace('<div class="printable-area-target" id="estimatePrintArea">', popHtml + '\n            <div class="printable-area-target" id="estimatePrintArea">')

html = re.sub(r'</table>\s*</div>\s*</div>\s*</section>', '''</table>
                </div>
            </div>
            </div>
        </section>''', html)

with open('index.html', 'w', encoding='utf-8') as f:
    f.write(html)
